import { test, expect } from '@playwright/test';

test.describe('Save Search Query Feature', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should successfully save a search query and display confirmation', async ({ page }) => {
    // Setup: intercept the save API call
    await page.route('**/api/search/save', (route) => {
      route.continue();
    });

    // Setup: intercept the success response
    await page.route('**/api/search/save', (route) => {
      route.abort('failed');
    });

    // Setup: intercept the success response
    await page.route('**/api/search/save', (route) => {
      route.continue();
    });

    // Enter search term
    const searchInput = page.getByPlaceholder('Search products...');
    await searchInput.fill('laptop');

    // Apply filter
    const categoryFilter = page.getByRole('button', { name: 'Electronics & Appliances' });
    await categoryFilter.click();

    // Apply price range filter
    const priceRangeFilter = page.getByRole('button', { name: 'Price Range' });
    await priceRangeFilter.click();
    const priceInput = page.getByLabel('Min Price');
    await priceInput.fill('500');

    // Click save button
    const saveButton = page.getByRole('button', { name: 'Save Search' });
    await saveButton.click();

    // Wait for API response
    await page.waitForResponse(response =>
      response.url().includes('/api/search/save') && response.status() === 200
    );

    // Verify success message
    const successMessage = page.getByText('Search query saved successfully');
    await expect(successMessage).toBeVisible();

    // Verify save button is disabled after successful save
    await expect(saveButton).toBeDisabled();

    // Verify confirmation icon appears
    const confirmationIcon = page.getByRole('img', { name: 'Saved' });
    await expect(confirmationIcon).toBeVisible();
  });

  test('should handle API errors when saving a search query', async ({ page }) => {
    // Setup: intercept the save API call and return an error
    await page.route('**/api/search/save', (route) => {
      route.abort('failed');
    });

    // Enter search term
    const searchInput = page.getByPlaceholder('Search products...');
    await searchInput.fill('monitor');

    // Apply filter
    const brandFilter = page.getByRole('button', { name: 'Brand' });
    await brandFilter.click();
    const brandOption = page.getByRole('option', { name: 'Dell' });
    await brandOption.click();

    // Click save button
    const saveButton = page.getByRole('button', { name: 'Save Search' });
    await saveButton.click();

    // Wait for API error response
    await page.waitForResponse(response =>
      response.url().includes('/api/search/save') && response.status() === 500
    );

    // Verify error message is displayed
    const errorMessage = page.getByText('Failed to save search query. Please try again.');
    await expect(errorMessage).toBeVisible();

    // Verify save button is still enabled for retry
    await expect(saveButton).toBeEnabled();

    // Verify error icon is visible
    const errorIcon = page.getByRole('img', { name: 'Error' });
    await expect(errorIcon).toBeVisible();

    // Verify search results are still visible
    const resultsContainer = page.getByRole('region', { name: 'Search Results' });
    await expect(resultsContainer).toBeVisible();
  });
});
